/bin/bash -lc "node --input-type=module - <<'EOF'
import assert from 'node:assert/strict';
import { resolvePermissions } from './src/resolve-permissions.js';

assert.deepEqual(resolvePermissions(
  [{ permission: 'read', allow: true }, { permission: 'read', scope: 'team', allow: false }],
  ['read', { permission: 'read', scope: 'team' }, { permission: 'read', scope: 'other' }]
), [
  { permission: 'read', scope: undefined, allowed: true },
  { permission: 'read', scope: 'team', allowed: false },
  { permission: 'read', scope: 'other', allowed: true }
]);
assert.equal(resolvePermissions(
  [{ permission: 'read', scope: 'team', allow: false }, { permission: 'read', scope: 'team', allow: true }],
  [{ permission: 'read', scope: 'team' }]
)[0].allowed, false);
for (const bad of [null, {}, [], 1, { permission: 'x', allow: true, scope: null }]) {
  assert.throws(() => resolvePermissions([bad], []), TypeError);
}
for (const bad of [null, {}, [], 1, { permission: 'x', scope: null }]) {
  assert.throws(() => resolvePermissions([], [bad]), TypeError);
}
console.log('contract edge checks passed');
EOF"

